const DAY = 864e5, now = Date.now();
const stages = Object.fromEntries(($('Pipeline stages').first().json.results || []).flatMap(p => p.stages)
  .map(s => [s.id, { label: s.label, p: Number(s.metadata?.probability || 0) }]));
const deals = $('Deals').first().json.results || [];
const dealContact = Object.fromEntries(($('Deal contacts').first().json.results || []).map(r => [String(r.from.id), String(r.to[0]?.toObjectId || '')]));
const source = Object.fromEntries(($json.results || []).map(c => [String(c.id), c.properties.lead_source || 'unknown']));
const val = (d) => Number(d.properties.weekly_value_ngn || 0);
const ngn = (n) => '₦' + Math.round(n).toLocaleString('en-NG');
const open = deals.filter(d => d.properties.hs_is_closed !== 'true');
const newDeals = deals.filter(d => now - new Date(d.properties.createdate) < 7 * DAY);
const bySource = {}; for (const d of newDeals) { const s = source[dealContact[d.id]] || 'unknown'; bySource[s] = (bySource[s] || 0) + 1; }
const byStage = {}; for (const d of open) { const s = stages[d.properties.dealstage]?.label || d.properties.dealstage; byStage[s] = (byStage[s] || 0) + val(d); }
const weighted = open.reduce((a, d) => a + val(d) * (stages[d.properties.dealstage]?.p || 0), 0);
const month = deals.filter(d => d.properties.hs_is_closed === 'true');
const won = month.filter(d => d.properties.hs_is_closed_won === 'true');
const lost = month.filter(d => d.properties.hs_is_closed_won !== 'true');
const entered = (d) => new Date(d.properties.hs_v2_date_entered_current_stage || d.properties.hs_lastmodifieddate).getTime();
const stuck = open.filter(d => now - entered(d) > 14 * DAY).sort((a, b) => entered(a) - entered(b)).slice(0, 3);
const summary = [
  'Harvest Lane pipeline · Monday',
  `New deals by source (7 days): ${Object.entries(bySource).map(([k, v]) => `${k} ${v}`).join(' · ') || 'none'}`,
  `Open value by stage: ${Object.entries(byStage).map(([k, v]) => `${k} ${ngn(v)}`).join(' · ') || 'none'}`,
  `Won this month: ${won.length} (${won.map(d => d.properties.dealname).join(', ') || '-'})`,
  `Lost this month: ${lost.length} (${lost.map(d => `${d.properties.dealname}: ${d.properties.lost_reason || 'no reason!'}`).join('; ') || '-'})`,
  `Weighted forecast (weekly): ${ngn(weighted)}`,
].join('\n');
return stuck.length
  ? stuck.map(d => ({ json: { summary, deal_id: d.id, dealname: d.properties.dealname, days: Math.floor((now - entered(d)) / DAY), stage: stages[d.properties.dealstage]?.label || '' } }))
  : [{ json: { summary, deal_id: '', dealname: '', days: 0, stage: '' } }];

