let stuck = [];
try {
  stuck = $('One-line summary').all().map((i, k) => {
    const d = $('Has stuck deals?').all()[k]?.json || {};
    return `- ${d.dealname} (${d.days} days in ${d.stage}): ${String(i.json.text || '').trim()}`;
  });
} catch (e) {}
const summary = $('Numbers').first().json.summary;
return [{ json: { text: summary + '\n\nOldest stuck deals:\n' + (stuck.join('\n') || '(none over 14 days)') } }];
